def svg(n,extra=''):
    inner=''.join(p if p.startswith('<') else f'<path d="{p}"/>' for p in P[n])
    return f'<svg viewBox="0 0 24 24" width="1.15em" height="1.15em" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-0.2em;flex:none" {extra}>{inner}</svg>'
DOT='<svg viewBox="0 0 10 10" width="0.55em" height="0.55em" style="vertical-align:0.05em"><circle cx="5" cy="5" r="5" fill="currentColor"/></svg>'
STATUS='<svg width="44" height="12" viewBox="0 0 44 12"><rect x="0" y="8" width="3" height="4" rx="1" fill="#1C1B1F"/><rect x="5" y="5" width="3" height="7" rx="1" fill="#1C1B1F"/><rect x="10" y="2" width="3" height="10" rx="1" fill="#1C1B1F"/><rect x="19" y="2" width="21" height="10" rx="3" fill="none" stroke="#1C1B1F" stroke-width="1.5"/><rect x="21.5" y="4.5" width="14" height="5" rx="1.5" fill="#1C1B1F"/><rect x="41" y="5" width="2" height="4" rx="1" fill="#1C1B1F"/></svg>'
MAP=[('▂▄▆ ▭',STATUS),('✓✓','check-check'),('📶','wifi'),('📵','wifioff'),('▦','qr'),('⚠','alert'),('🔒','lock'),('◌','spin'),('⧉','copy'),('↻','refresh'),('↺','undo'),('➤','send'),('←','back'),('✓','check'),
('👛','wallet'),('✉','mail'),('🤖','bot'),('👥','users'),('📣','mega'),('🏫','school'),('📅','cal'),('🗓','caldays'),('⏰','alarm'),('📊','chart'),('🙂','smile'),('⚡','zap'),('🧪','flask'),('ⓘ','info'),('›','chev'),('−','minus'),('＋','plus'),('●',DOT),('▸','chev'),('→','arrow')]
def convert(html):
    import re
    html=re.sub(r'\[\[(\w+)\]\]',lambda m:svg(m.group(1)),html)
    html=html.replace(' 👋','')
    for k,v in MAP:
        html=html.replace(k, v if v.startswith('<') else svg(v))
    return html
